<?php
session_start();require_once('dbstring.php');require_once('check-login.php');require_once('early-years-utils.php');require_once('student-attendance-utils.php');eya_ensure_tables($con);$admin=eya_admin();$teacherId=trim((string)$_SESSION['USERID']);$assignments=student_attendance_list_assignments($con,$teacherId,!$admin);$assignmentId=trim((string)($_REQUEST['assignmentid']??''));$skillId=(int)($_REQUEST['skillid']??0);$selected=null;foreach($assignments as $a)if($a['assignmentid']===$assignmentId)$selected=$a;$skills=mysqli_query($con,"SELECT * FROM tblearlyyearsskill WHERE status='active' ORDER BY display_order,skillname");$message='';
if(isset($_POST['save_ratings'])&&$selected&&hash_equals(eya_csrf(),$_POST['csrf']??'')){$skillId=(int)$_POST['skillid'];$students=$_POST['student']??array();$ratings=$_POST['rating']??array();$comments=$_POST['comment']??array();$stmt=mysqli_prepare($con,'INSERT INTO tblearlyyearsassessment(userid,skillid,batchid,termname,rating,teachercomment,recordedby) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),teachercomment=VALUES(teachercomment),recordedby=VALUES(recordedby)');foreach($students as $student){$rating=(int)($ratings[$student]??0);if($rating<1||$rating>4)continue;$comment=substr(trim((string)($comments[$student]??'')),0,500);mysqli_stmt_bind_param($stmt,'sisiiss',$student,$skillId,$selected['batchid'],$selected['termname'],$rating,$comment,$teacherId);mysqli_stmt_execute($stmt);}mysqli_stmt_close($stmt);$message='Ratings saved.';}
$students=array();$ratings=array();if($selected&&$skillId){$class=mysqli_real_escape_string($con,$selected['classid']);$batch=mysqli_real_escape_string($con,$selected['batchid']);$r=mysqli_query($con,"SELECT su.userid,su.firstname,su.othernames,su.surname FROM tblclass cl INNER JOIN tblsystemuser su ON su.userid=cl.userid WHERE cl.class_entryid='$class' AND cl.batchid='$batch' AND cl.status='active' AND su.systemtype='Student' ORDER BY su.firstname,su.surname");while($r&&($row=mysqli_fetch_assoc($r))){$students[]=$row;}$old=mysqli_query($con,"SELECT userid,rating,teachercomment FROM tblearlyyearsassessment WHERE skillid=$skillId AND batchid='$batch' AND termname=".(int)$selected['termname']);while($old&&($row=mysqli_fetch_assoc($old))){$ratings[$row['userid']]=$row;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Early Years Assessment</title><style>body{margin:0;background:#f3f7fa;color:#183650;font:15px Arial}.wrap{max-width:1100px;margin:28px auto;padding:0 18px}.hero{padding:25px;border-radius:17px;background:linear-gradient(120deg,#163656,#08766f);color:#fff}.hero h1{margin:4px 0;font:600 30px Georgia}.card{margin-top:18px;background:#fff;border:1px solid #d7e2ea;border-radius:14px;padding:20px}select,input{padding:9px;border:1px solid #c8d6e2;border-radius:7px;font:inherit}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e4edf2}textarea{width:100%;min-height:45px;padding:8px;border:1px solid #c8d6e2;border-radius:7px}button,a{display:inline-block;padding:10px 13px;border:0;border-radius:7px;background:#08766f;color:#fff;text-decoration:none;font-weight:bold}.msg{padding:11px;background:#e6f7ef;color:#126443;border-radius:7px}</style></head><body><main class="wrap"><section class="hero"><a href="<?php echo $admin?'admin.php':'teacher-page.php';?>" style="color:#fff">← Dashboard</a><h1>Early Years continuous assessment</h1><p>Rate learning behaviours: 1 = Beginning, 2 = Developing, 3 = Secure, 4 = Excelling.</p></section><section class="card"><form method="get"><label>Class group <select name="assignmentid" onchange="this.form.submit()"><option value="">Select class…</option><?php foreach($assignments as $a){?><option value="<?php echo eya_safe($a['assignmentid']);?>" <?php echo $selected&&$a['assignmentid']===$selected['assignmentid']?'selected':'';?>><?php echo eya_safe($a['class_name'].' · '.$a['batch'].' · Term '.$a['termname']);?></option><?php }?></select></label><?php if($selected){?><label>Skill <select name="skillid" onchange="this.form.submit()"><option value="">Select skill…</option><?php while($skill=mysqli_fetch_assoc($skills)){?><option value="<?php echo (int)$skill['skillid'];?>" <?php echo $skillId===$skill['skillid']?'selected':'';?>><?php echo eya_safe($skill['category'].' — '.$skill['skillname']);?></option><?php }?></select></label><input type="hidden" name="assignmentid" value="<?php echo eya_safe($assignmentId);?>"><?php }?></form></section><?php if($message){?><p class="msg"><?php echo eya_safe($message);?></p><?php }if($selected&&$skillId){?><section class="card"><form method="post"><input type="hidden" name="csrf" value="<?php echo eya_safe(eya_csrf());?>"><input type="hidden" name="assignmentid" value="<?php echo eya_safe($assignmentId);?>"><input type="hidden" name="skillid" value="<?php echo $skillId;?>"><table><thead><tr><th>Pupil</th><th>Rating</th><th>Brief teacher comment</th></tr></thead><tbody><?php foreach($students as $student){$id=$student['userid'];$name=trim($student['firstname'].' '.$student['othernames'].' '.$student['surname']);?><tr><td><?php echo eya_safe($name);?><input type="hidden" name="student[]" value="<?php echo eya_safe($id);?>"></td><td><select name="rating[<?php echo eya_safe($id);?>]"><option value="">—</option><?php for($i=1;$i<=4;$i++){?><option value="<?php echo $i;?>" <?php echo isset($ratings[$id])&&$ratings[$id]['rating']==$i?'selected':'';?>><?php echo $i;?></option><?php }?></select></td><td><textarea name="comment[<?php echo eya_safe($id);?>]"><?php echo eya_safe($ratings[$id]['teachercomment']??'');?></textarea></td></tr><?php }?></tbody></table><button name="save_ratings">Save assessment</button></form></section><?php }?></main></body></html>
